import React, { useEffect, useState } from "react";
import axios from "axios";

interface Delivery {
  _id: string;
  customerId: string;
  driverId: string;
  status: string;
  location: {
    lat: number;
    lng: number;
  };
}

export default function DeliveryList() {
  const [deliveries, setDeliveries] = useState<Delivery[]>([]);
  const [error, setError] = useState("");

  useEffect(() => {
    axios
      .get("http://localhost:5000/api/delivery")
      .then((res) => {
        console.log("📦 Received deliveries:", res.data);
        alert("Deliveries found: " + res.data.length);
        setDeliveries(res.data);
      })
      .catch((err) => {
        console.error("❌ Failed to fetch deliveries:", err);
        setError("API call failed. Check your backend.");
      });
  }, []);

  return (
    <div>
      <h2>All Deliveries</h2>

      {error && <p style={{ color: "red" }}>{error}</p>}

      {deliveries.length === 0 ? (
        <p>No deliveries available.</p>
      ) : (
        <ul>
          {deliveries.map((d) => (
            <li key={d._id}>
              📦 <strong>{d.customerId}</strong> – Status: {d.status}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}
